<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requirePermission('competitors.view');$pdo=Database::connection();
$q=trim((string)($_GET['q']??''));$type=(string)($_GET['type']??'');$complete=(string)($_GET['complete']??'');
// This is deliberately identical to the production-proven signed API WDC directory query.
$sql="SELECT w.id,w.identity_code,w.entry_type,w.display_name,w.country,w.solo_competitor_id,w.photo_url,c.photo_url shared_photo,COUNT(r.id) registration_count,GROUP_CONCAT(CONCAT(r.event_key,':',r.category_key) ORDER BY r.event_key,r.category_key SEPARATOR ',') registrations FROM bdc_wdc_identities w LEFT JOIN bdc_competitors c ON c.id=w.solo_competitor_id LEFT JOIN bdc_wdc_registrations r ON r.wdc_identity_id=w.id AND r.status='registered' WHERE w.status='active' GROUP BY w.id,w.identity_code,w.entry_type,w.display_name,w.country,w.solo_competitor_id,w.photo_url,c.photo_url ORDER BY LOWER(w.display_name),w.id LIMIT 500";
$rows=$pdo->query($sql)->fetchAll();$normal=static fn(string $v):string=>function_exists('mb_strtolower')?mb_strtolower($v,'UTF-8'):strtolower($v);
$rows=array_values(array_filter($rows,static function(array $r)use($q,$type,$complete,$normal):bool{$photo=trim((string)($r['photo_url']?:$r['shared_photo']));$haystack=$normal(implode(' ',[(string)$r['display_name'],(string)$r['identity_code'],(string)$r['country'],(string)$r['registrations']]));return !($q!==''&&!str_contains($haystack,$normal($q)))&&!($type!==''&&$r['entry_type']!==$type)&&!($complete==='missing_photo'&&$photo!=='')&&!($complete==='missing_country'&&trim((string)$r['country'])!=='')&&!($complete==='no_registration'&&(int)$r['registration_count']>0);})) ;
$registrationCount=array_sum(array_map(static fn(array $r):int=>(int)$r['registration_count'],$rows));$missingPhoto=count(array_filter($rows,static fn(array $r):bool=>trim((string)($r['photo_url']?:$r['shared_photo']))===''));
function dclabel(?string $v):string{return ucwords(str_replace(['_','-'], ' ',(string)$v));}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Competitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}.photo{width:58px;height:68px;object-fit:cover;border-radius:10px}.registration{display:block;border-left:3px solid #0d6efd;padding-left:.5rem;margin:.2rem 0}.actions{display:flex;gap:.35rem;flex-wrap:wrap}</style></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="<?=e(url('admin/'))?>">BDC Admin</a><a class="btn btn-outline-light btn-sm" href="<?=e(url('admin/dance-cup/'))?>">Dance Cup Scoring</a></div></nav><main class="container-fluid py-4" style="max-width:1650px"><div class="d-flex justify-content-between gap-3 flex-wrap mb-3"><div><h1 class="h3 mb-1">Dance Cup Competitor</h1><p class="text-muted mb-0">One permanent WDC identity with its active registrations.</p></div><?php if(Auth::can('competitors.edit')):?><a class="btn btn-dark" href="competitor-edit.php">Add competitor</a><?php endif;?></div><section class="summary mb-4"><?php foreach(['WDC identities'=>count($rows),'Active registrations'=>$registrationCount,'Missing photos'=>$missingPhoto] as $title=>$value):?><div class="card border-0 shadow-sm"><div class="card-body"><div class="small text-muted"><?=e($title)?></div><strong class="fs-2"><?=$value?></strong></div></div><?php endforeach;?></section><form class="card border-0 shadow-sm mb-3"><div class="card-body row g-2"><div class="col-lg-6"><label class="form-label">Search</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Name, WDC ID, country or registration"></div><div class="col-lg-2"><label class="form-label">Entry type</label><select class="form-select" name="type"><option value="">All types</option><?php foreach(['solo','couple','duo','pro_am','team'] as $v):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=e(dclabel($v))?></option><?php endforeach;?></select></div><div class="col-lg-2"><label class="form-label">Completeness</label><select class="form-select" name="complete"><option value="">Any</option><option value="missing_photo" <?=$complete==='missing_photo'?'selected':''?>>Missing photo</option><option value="missing_country" <?=$complete==='missing_country'?'selected':''?>>Missing country</option><option value="no_registration" <?=$complete==='no_registration'?'selected':''?>>No registration</option></select></div><div class="col-lg-2 d-flex align-items-end gap-2"><button class="btn btn-dark">Apply</button><a class="btn btn-outline-secondary" href="competitors.php">Reset</a></div></div></form><section class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Photo</th><th>WDC ID</th><th>Participant</th><th>Country</th><th>Registrations</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr id="wdc-<?=(int)$r['id']?>"><td><img class="photo" src="<?=e($r['photo_url']?:$r['shared_photo']?:url('public/assets/img/default-competitor.svg'))?>" alt=""></td><td><code><?=e($r['identity_code'])?></code></td><td><strong><?=e($r['display_name'])?></strong><small class="d-block text-muted"><?=e(dclabel($r['entry_type']))?></small></td><td><?=e($r['country']?:'—')?></td><td><?php foreach(array_filter(explode(',',(string)$r['registrations'])) as $registration):?><span class="registration"><?=e(dclabel(str_replace(':',' · ',$registration)))?></span><?php endforeach;?><?php if(!(int)$r['registration_count']):?><span class="text-muted">No active registration</span><?php endif;?></td><td><div class="actions"><?php if(Auth::can('competitors.edit')):?><a class="btn btn-sm btn-dark" href="competitor-edit.php?id=<?=(int)$r['id']?>">Edit WDC</a><a class="btn btn-sm btn-outline-primary" href="photo-adjust.php?id=<?=(int)$r['id']?>">Adjust photo</a><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-5">No Dance Cup competitors match the selected filters.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
